import { useId, useMemo, useState } from 'react';
import { useLocale, useT } from '../i18n';
import { Rich } from '../i18n/Rich';
import { InfoLayout } from './InfoLayout';
import { I, ICONS } from './icons';
import LICENSES from './licenses.json';

/** One shipped package; generated by scripts/gen-licenses.cjs. */
interface Pkg { name: string; version: string; license: string; url: string }

const ALL = LICENSES as Pkg[];

export function LicensesPage() {
  const t = useT();
  const locale = useLocale();
  const [query, setQuery] = useState('');
  const [license, setLicense] = useState<string | null>(null);
  const searchId = useId();

  const groups = useMemo(() => {
    const m = new Map<string, number>();
    for (const p of ALL) m.set(p.license, (m.get(p.license) ?? 0) + 1);
    return [...m.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  }, []);

  const q = query.trim().toLowerCase();
  const shown = ALL.filter((p) => (!license || p.license === license) && (!q || p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q)));
  const byLicense = groups.map(([l]) => [l, shown.filter((p) => p.license === l)] as const).filter(([, list]) => list.length);

  return (
    <InfoLayout title="lic.title" kicker="lic.kicker" h1="lic.h1" lead="lic.lead" wide>
      <section aria-labelledby="lic-own">
        <h2 id="lic-own">{t('lic.own.h')}</h2>
        <p><Rich text={t('lic.own.b')} /></p>
      </section>
      <section aria-labelledby="lic-deps">
        <h2 id="lic-deps">{t('lic.deps.h')}</h2>
        <p>{t('lic.deps.b', { n: ALL.length.toLocaleString(locale) })}</p>
        <div className="lic-filters" role="group" aria-label={t('lic.deps.h')}>
          <button type="button" className={'lic-chip' + (license === null ? ' on' : '')} aria-pressed={license === null} onClick={() => setLicense(null)}>
            {t('lic.all')} <span>{ALL.length}</span>
          </button>
          {groups.map(([l, n]) => (
            <button key={l} type="button" className={'lic-chip' + (license === l ? ' on' : '')} aria-pressed={license === l} onClick={() => setLicense(license === l ? null : l)}>
              {l} <span>{n}</span>
            </button>
          ))}
        </div>
        <label className="search lic-search" htmlFor={searchId}>
          <I d={ICONS.search} />
          <span className="sr">{t('lic.search')}</span>
          <input id={searchId} type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t('lic.searchPh')} />
        </label>
        <p className="lic-count" aria-live="polite">{t('lic.shown', { n: shown.length, total: ALL.length })}</p>
        {shown.length === 0 && <p className="lic-none">{t('lic.none', { q: query })}</p>}
        {byLicense.map(([l, list]) => (
          <div key={l} className="lic-group">
            <h3>{l} <span>· {list.length}</span></h3>
            <ul className="lic-list">
              {list.map((p) => (
                <li key={p.name + p.version}>
                  <a href={p.url} target="_blank" rel="noopener noreferrer">{p.name}</a>
                  <span className="lic-ver">{p.version}</span>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </section>
    </InfoLayout>
  );
}
